using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Gives the in-game phone the game's look at runtime: a pearl-and-gold body like the Gate of Memories,
/// the team's cover art as wallpaper (Resources/UI/phone_home.png and phone_lock.png, generated by
/// _work/gen_phone.py on the exact screen area of the original phone.png), the May 2026 calendar with
/// 13 circled kept on the lock screen as the password clue, and themed text, inputs and buttons.
/// </summary>
public static class PhoneSkin
{
    public static void Apply(GameObject phone, GameObject lockScreen)
    {
        if (phone == null) return;
        // PhoneManager's phonePanel is the frame image itself: style the whole phone it belongs to
        Transform rootT = phone.transform;
        while (lockScreen != null && !lockScreen.transform.IsChildOf(rootT) && rootT.parent != null) rootT = rootT.parent;
        phone = rootT.gameObject;

        var home = UiTheme.FromResources("UI/phone_home");
        var locked = UiTheme.FromResources("UI/phone_lock");
        foreach (var img in phone.GetComponentsInChildren<Image>(true))
        {
            if (img.name == "I16" && home != null) img.sprite = home;
            else if (img.name == "bg" && locked != null && lockScreen != null && img.transform.IsChildOf(lockScreen.transform)) img.sprite = locked;
        }
        foreach (var raw in phone.GetComponentsInChildren<RawImage>(true))
        {
            if (raw.name == "I16" && home != null) raw.texture = home.texture;
            else if (raw.name == "bg" && locked != null) raw.texture = locked.texture;
        }

        foreach (var t in phone.GetComponentsInChildren<TMP_Text>(true))
        {
            switch (t.name)
            {
                case "Time":
                    UiTheme.Style(t, true, t.fontSize, UiTheme.Pearl, 0.55f);
                    break;
                case "Date":
                    UiTheme.Style(t, false, t.fontSize, UiTheme.Pearl, 0.55f);
                    break;
                case "Noti (TMP)":
                    UiTheme.Style(t, true, t.fontSize, new Color(0.85f, 0.25f, 0.3f), 0f);
                    break;
                default:
                    // labels on the light wallpaper and inside the note app: dark ink
                    UiTheme.Style(t, t.fontStyle.HasFlag(FontStyles.Bold) || t.name == "Text (TMP)" && t.text.Contains("Note"),
                        t.fontSize, UiTheme.Ink, 0f);
                    break;
            }
        }

        var round = UiTheme.RoundedRect(16);
        foreach (var input in phone.GetComponentsInChildren<TMP_InputField>(true))
        {
            var bg = input.GetComponent<Image>();
            if (bg != null)
            {
                bg.sprite = round;
                bg.type = Image.Type.Sliced;
                bg.color = new Color(1f, 1f, 1f, 0.82f);
            }
            if (input.textComponent != null) input.textComponent.color = UiTheme.Ink;
            if (input.placeholder is TMP_Text ph) ph.color = new Color(UiTheme.Ink.r, UiTheme.Ink.g, UiTheme.Ink.b, 0.45f);
            input.caretColor = UiTheme.GoldDeep;
            input.selectionColor = new Color(UiTheme.Gold.r, UiTheme.Gold.g, UiTheme.Gold.b, 0.4f);
        }

        foreach (var button in phone.GetComponentsInChildren<Button>(true))
        {
            if (button.GetComponentInParent<TMP_InputField>() != null) continue;
            var bg = button.GetComponent<Image>();
            var label = button.GetComponentInChildren<TMP_Text>(true);
            bool isTextButton = label != null && !string.IsNullOrEmpty(label.text) && label.text.Trim().Length > 0;
            if (bg != null && isTextButton)
            {
                bg.sprite = round;
                bg.type = Image.Type.Sliced;
                bg.color = new Color(UiTheme.Gold.r, UiTheme.Gold.g, UiTheme.Gold.b, 0.92f);
                var colors = button.colors;
                colors.highlightedColor = new Color(1f, 0.97f, 0.9f);
                colors.pressedColor = new Color(0.85f, 0.8f, 0.72f);
                button.colors = colors;
                UiTheme.Style(label, true, label.fontSize, UiTheme.Night, 0f);
            }
        }
    }
}
